import type { BlogArticleFaq } from '../../../types/blog';

export const BODY: string = "\n<p>Gambar adalah bagian terberat dari kebanyakan website. Halaman yang termuat lambat biasanya punya gambar yang harus disalahkan, dan memperbaikinya adalah kemenangan kecepatan tercepat yang tersedia.</p>\n<p>Panduan ini membahas seluruh proses optimasi. Anda akan mengaudit halaman, memilih preset yang tepat, mengoptimasi gambar, dan menempel HTML ke tempatnya.</p>\n<p>Ini berlaku untuk blog, toko, dan situs bisnis, dan Anda tidak butuh pengalaman coding selain menyalin dan menempel.</p>\n<h2 id=\"audit-first\">Langkah 1: Audit Dulu Halamannya</h2>\n<p>Sebelum mengoptimasi apa pun, cari tahu gambar mana yang menjadi masalah. Buka halaman dan catat gambar mana yang tampak lambat muncul.</p>\n<p>Gunakan alat kecepatan gratis untuk mengukur halaman. Ia mencantumkan gambar terberat dan menunjukkan berapa biaya masing-masing dalam waktu muat.</p>\n<p>Catat total bobot gambar halaman itu. Halaman dengan 5MB gambar punya masalah yang jelas, sedangkan halaman dengan 500KB sudah dalam kondisi baik.</p>\n<p>Tuliskan tiga gambar terburuk. Memperbaiki ketiganya dulu memberi peningkatan kecepatan terbesar dengan usaha paling sedikit.</p>\n<h2 id=\"step-2-open\">Langkah 2: Buka Alat Optimasi Gambar Web</h2>\n<p>Buka <a href=\"/id/optimalkan-gambar-untuk-web/\">alat optimasi gambar web</a> di browser Anda. Tidak butuh akun atau pemasangan apa pun.</p>\n<p>Alat berjalan sepenuhnya di perangkat Anda. Gambar Anda diproses secara lokal dan tidak pernah diunggah ke server.</p>\n<p>Jika Anda mengoptimasi seluruh situs, kerjakan dalam batch. Tiga puluh gambar sekaligus adalah ukuran batch yang nyaman untuk kebanyakan browser.</p>\n<p>Tandai halaman itu. Optimasi gambar adalah pekerjaan yang berulang, dan alat ini akan sering Anda kunjungi lagi.</p>\n<h2 id=\"step-3-preset\">Langkah 3: Pilih Preset yang Tepat</h2>\n<p>Pilih preset yang cocok dengan tempat gambar akan tampil. Gambar utama, foto produk, dan thumbnail masing-masing punya preset sendiri.</p>\n<p>Preset Produk E-Commerce adalah bawaannya. Ia membatasi gambar di lebar 1200 piksel dalam WebP pada kualitas 82 persen, dan itu cocok untuk kebanyakan foto produk.</p>\n<p>Untuk gambar fitur blog, gunakan preset gambar utama atau kartu tergantung tata letaknya. Samakan preset dengan ukuran tampilan, bukan dengan ukuran file.</p>\n<p>Untuk gambar berbagi sosial, gunakan preset OG Sosial. Ia beralih format ke JPG secara otomatis, karena platform sosial lebih menyukainya.</p>\n<h2 id=\"step-4-upload\">Langkah 4: Unggah Gambar</h2>\n<p>Seret gambar ke area unggah atau ketuk untuk menjelajah. File JPG, PNG, WebP, dan HEIC diterima.</p>\n<p>Unggah original berkualitas tertinggi yang Anda punya. Original 12 megapiksel memberi alat optimasi jauh lebih banyak bahan daripada salinan kecil.</p>\n<p>Untuk batch, tambahkan semua gambar untuk satu halaman sekaligus. Mereka berbagi preset, dan itu menjaga hasilnya tetap konsisten.</p>\n<p>Tunggu unggahan selesai sebelum mengubah pengaturan. Alat butuh file lengkap sebelum bisa mengoptimasinya.</p>\n<h2 id=\"step-5-customise\">Langkah 5: Sesuaikan Pengaturan</h2>\n<p>Setelah memilih preset, sesuaikan pengaturan bila slot menuntutnya. Ubah dimensi, format, atau kualitas supaya cocok dengan desain.</p>\n<p>Pertahankan dimensi mendekati ukuran tampilan. Gambar yang ditampilkan selebar 800 piksel tidak perlu selebar 2400 piksel dalam file.</p>\n<p>Aktifkan Hanya perkecil ketika batch mencampur gambar besar dan kecil. Ia melindungi ikon dan thumbnail dari peregangan yang lebih besar.</p>\n<p>Gerakkan slider kualitas hanya bila dibutuhkan. Kebanyakan preset berada di antara 75 dan 85 persen, dan itu rentang yang tepat untuk hampir setiap gambar.</p>\n<h2 id=\"step-6-preview\">Langkah 6: Lihat Pratinjau Hasil</h2>\n<p>Lihat pratinjau setiap gambar yang dioptimalkan pada ukuran penuh sebelum mengunduh. Gambar kecil menyembunyikan masalah yang jelas pada ukuran penuh.</p>\n<p>Periksa detail halus dulu. Tekstur kain, teks, dan tepi adalah hal pertama yang melembut di bawah kompresi.</p>\n<p>Bandingkan beberapa hasil dengan originalnya. Perbedaan kecil itu normal; teks yang tidak terbaca atau kulit yang bercak bukan.</p>\n<p>Periksa juga ukuran filenya. Ringkasan menunjukkan seberapa banyak setiap gambar mengecil dan total penghematan di seluruh batch.</p>\n<h2 id=\"step-7-copy-html\">Langkah 7: Salin Tag HTML</h2>\n<p>Klik Salin Tag Gambar untuk setiap gambar. Tag itu mencakup sumber, dimensi, teks alt, dan perilaku pemuatan, dan siap ditempel.</p>\n<p>Periksa teks alt di dalam tag. Edit bila teks yang dihasilkan tidak menjelaskan gambar dengan baik.</p>\n<p>Pastikan atribut pemuatannya benar. Gambar utama harus termuat segera, sedangkan gambar di bawah lipatan harus dimuat secara malas.</p>\n<p>Tempel tag itu ke halaman Anda di tempat gambar itu berada. Ganti tag gambar lama sepenuhnya, bukan mengeditnya dengan tangan.</p>\n<h2 id=\"step-8-upload\">Langkah 8: Unggah dan Uji Halaman</h2>\n<p>Unggah gambar yang dioptimalkan ke situs Anda. Gunakan nama file yang sama seperti yang dihasilkan alat, supaya tag HTML cocok dengan file.</p>\n<p>Buka halaman di tab browser baru. Periksa setiap gambar muncul dan tidak ada yang tampak meregang atau buram.</p>\n<p>Jalankan lagi alat kecepatan dan bandingkan angkanya. Total bobot gambar seharusnya turun tajam, dan waktu muat ikut turun.</p>\n<p>Uji di ponsel sekaligus laptop. Kebanyakan pengunjung menelusuri lewat ponsel, dan halaman harus terasa cepat di sana dulu.</p>\n<h2 id=\"fixing-problems\">Memperbaiki Masalah Umum</h2>\n<p>Jika gambar tampak buram, sumbernya mungkin sudah terlalu kecil. Optimasi ulang dari original yang lebih besar dengan preset yang sama.</p>\n<p>Jika halaman tetap termuat lambat, periksa gambar yang belum dioptimalkan. Satu banner 5MB yang terlupakan bisa membatalkan seluruh batch.</p>\n<p>Jika gambar tampak meregang, dimensi di tag tidak cocok dengan file. Salin ulang tag dari alat, bukan mengeditnya dengan tangan.</p>\n<p>Jika berbagi sosial tidak menampilkan gambar, periksa formatnya. Platform sosial lebih suka JPG, dan preset OG Sosial menangani itu secara otomatis.</p>\n<h2 id=\"blog-workflow\">Alur Kerja: Artikel Blog</h2>\n<p>Kumpulkan gambar untuk artikel dan unggah sebagai satu batch. Gunakan preset kartu untuk thumbnail dan preset gambar utama untuk gambar fitur.</p>\n<p>Lihat pratinjau gambar fitur dengan teliti. Ia adalah gambar terbesar di halaman dan yang pertama kali dinilai pembaca.</p>\n<p>Salin tag HTML dan tempel ke artikel. Periksa teks alt pada masing-masing sebelum menerbitkan.</p>\n<p>Terbitkan artikel dan uji di ponsel. Gambar harus termuat cepat dan tampak tajam saat Anda menggulir.</p>\n<h2 id=\"shop-workflow\">Alur Kerja: Halaman Produk</h2>\n<p>Kumpulkan foto produk dan unggah sebagai satu batch. Gunakan preset Produk E-Commerce untuk hasil yang konsisten.</p>\n<p>Lihat pratinjau produk yang paling detail dulu. Tekstur kain dan label cetak adalah hal pertama yang melembut.</p>\n<p>Salin tag HTML dan tempel ke halaman produk. Pastikan atribut pemuatan benar untuk setiap posisi gambar.</p>\n<p>Periksa halaman produk di ponsel setelah mengunggah. Kebanyakan pembeli menelusuri lewat ponsel, dan gambar harus tampak bagus di sana.</p>\n<h2 id=\"speed-tools\">Memanfaatkan Alat Kecepatan Gratis dengan Baik</h2>\n<p>Alat kecepatan gratis mengukur halaman Anda dan mencantumkan masalahnya. Mereka adalah titik awal terbaik untuk pekerjaan optimasi apa pun.</p>\n<p>Jalankan alat itu pada halaman tayang, bukan pada salinan lokal. Halaman tayang mencakup hosting, CDN, dan kondisi dunia nyata yang dihadapi pengunjung Anda.</p>\n<p>Baca dulu rekomendasi gambarnya. Mereka menyebutkan file persis yang paling banyak menghabiskan waktu, dan itu memberi tahu Anda harus mulai dari mana.</p>\n<p>Abaikan skor sempurna. Skor di zona hijau sudah cukup baik; mengejar 100 membuang waktu yang lebih baik dihabiskan untuk konten.</p>\n<p>Jalankan ulang alat itu setelah setiap putaran perbaikan. Angka yang berubah menunjukkan apakah pekerjaan Anda terbayar.</p>\n<h2 id=\"image-sizes-by-slot\">Memilih Ukuran Berdasarkan Slot Halaman</h2>\n<p>Setiap slot di halaman punya ukuran gambar yang alami. Menyesuaikan file dengan slot adalah keterampilan inti optimasi web.</p>\n<p>Gambar utama butuh file terbesar, sering selebar 1200 sampai 1600 piksel. Mereka memenuhi layar, jadi harus tetap tajam.</p>\n<p>Gambar fitur di artikel blog cocok di 800 sampai 1200 piksel. Mereka besar tetapi tidak selebar layar, jadi ukuran tengah bekerja.</p>\n<p>Thumbnail dan avatar hanya butuh 200 sampai 400 piksel. Apa pun yang lebih besar membuang bandwidth untuk detail yang tidak bisa dilihat siapa pun.</p>\n<p>Ukur slot di tema Anda sebelum memilih. Lebar yang ditampilkan menentukan lebar file, dan menebak dengan salah membuang kilobyte.</p>\n<h2 id=\"srcset-basics\">Gambar Responsif dalam Praktik</h2>\n<p>Gambar responsif menyajikan file berbeda untuk layar berbeda. Ponsel mendapat file kecil, sedangkan desktop mendapat file yang lebih besar.</p>\n<p>Atribut srcset mencantumkan ukuran yang tersedia, dan browser memilih yang tepat untuk layar tempat ia berjalan.</p>\n<p>Buat dua atau tiga ukuran per gambar. Ukuran ponsel, ukuran tablet, dan ukuran desktop mencakup hampir setiap pengunjung.</p>\n<p>Uji di ponsel sungguhan setelah menambahkan gambar responsif. Peningkatan pemuatan di ponsel sering dramatis.</p>\n<p>Pertahankan HTML tetap sederhana. Srcset dengan tiga ukuran sudah cukup; sepuluh ukuran menambah kerumitan tanpa manfaat yang terlihat.</p>\n<h2 id=\"image-seo\">SEO Gambar Saat Anda Mengoptimasi</h2>\n<p>Optimasi dan SEO berjalan bersama. Halaman cepat dengan gambar yang dideskripsikan dengan baik berperingkat lebih baik daripada halaman lambat dengan file anonim.</p>\n<p>Gunakan nama file yang deskriptif. Nama seperti blue-cotton-shirt.jpg memberi tahu mesin pencari apa yang ditampilkan gambar itu.</p>\n<p>Tulis teks alt yang nyata untuk setiap gambar. Jelaskan isinya dalam satu kalimat, dan sertakan detail kunci yang akan dicari pencari.</p>\n<p>Jangan menjejalkan kata kunci ke nama file atau teks alt. Deskripsi yang alami membantu pembaca dan mesin pencari.</p>\n<p>Kirim peta situs gambar jika situs Anda mengandalkan pencarian gambar. Itu membantu mesin pencari menemukan gambar yang mungkin terlewat.</p>\n<h2 id=\"maintenance\">Memelihara Gambar yang Dioptimalkan Seiring Waktu</h2>\n<p>Optimasi bukan pekerjaan satu kali. Gambar baru datang setiap minggu, dan masing-masing butuh perlakuan yang sama seperti yang terakhir.</p>\n<p>Bangun optimasi ke dalam daftar periksa penerbitan. Setiap artikel harus melewati alat optimasi sebelum tayang.</p>\n<p>Audit situs setiap tiga bulan. Gambar lama dari sebelum kebiasaan optimasi sering masih berat, dan satu batch memperbaikinya dengan cepat.</p>\n<p>Waspadai perubahan tema. Tema baru bisa menampilkan gambar lebih besar daripada yang lama, yang berarti file lama tiba-tiba terlalu kecil.</p>\n<p>Simpan original dengan aman. Ketika desain berubah, original memungkinkan Anda mengoptimasi ulang ke ukuran baru tanpa kehilangan kualitas.</p>\n<h2 id=\"team-optimisation\">Standar Optimasi untuk Tim</h2>\n<p>Tim yang menerbitkan bersama butuh standar yang sama. Sepakati preset, pola penamaan, dan anggaran ukuran sebelum artikel pertama.</p>\n<p>Tuliskan standar itu dalam satu halaman. Panduan singkat di wiki tim mencegah ratusan pertanyaan kecil.</p>\n<p>Tugaskan satu orang untuk memeriksa bobot gambar pada setiap penerbitan. Sepasang mata kedua menangkap gambar berat yang terlewat penulis.</p>\n<p>Tinjau standar ketika desain berubah. Preset yang cocok untuk tema tahun lalu mungkin tidak cocok untuk tata letak tahun ini.</p>\n<p>Standar yang bagus membuat kecepatan menjadi rutinitas. Tim berhenti memikirkan optimasi karena prosesnya menanganinya secara otomatis.</p>\n<h2 id=\"common-speed-myths\">Mitos Kecepatan yang Sebaiknya Diabaikan</h2>\n<p>Satu mitos mengatakan hanya beranda yang penting untuk kecepatan. Kenyataannya, pengunjung mendarat di artikel blog dan halaman produk, dan halaman itu juga harus cepat.</p>\n<p>Mitos lain mengatakan host yang cepat memperbaiki gambar yang lambat. Hosting memang membantu, tetapi gambar 5MB lambat di host mana pun, dan optimasi adalah satu-satunya perbaikan.</p>\n<p>Mitos ketiga mengatakan WebP saja menyelesaikan segalanya. Format memang membantu, tetapi dimensi dan pemuatan malas sama pentingnya dengan pilihan format.</p>\n<p>Kebenarannya membosankan dan praktis: ukuran yang tepat, format yang tepat, pemuatan malas di bawah lipatan, dan dimensi di setiap tag. Lakukan keempat hal itu dan halaman akan cepat.</p>\n<p>Uji halaman Anda sendiri untuk menyelesaikan pertanyaan itu. Angka kecepatan tidak peduli pada mitos, dan mereka akan memberi tahu Anda apa yang benar-benar berhasil.</p>\n<p>Periksa skor kecepatan Anda di PageSpeed Insights sebelum dan sesudah optimasi, supaya peningkatan itu terukur. Catat skor untuk tiga halaman terpenting Anda, lalu bandingkan setelah semua gambar dioptimalkan dan diunggah kembali. Angka yang membaik membuat manfaat optimasi nyata bagi klien atau tim Anda. Simpan tangkapan layar kedua skor itu untuk laporan Anda.</p>\n<p>Perhatikan gambar di halaman beranda, karena di sanalah pengunjung pertama kali menilai situs Anda. Gambar utama yang berat membuat kesan pertama itu lambat, dan pengunjung yang tidak sabar akan pergi sebelum melihat isi halaman. Gambar utama yang dioptimalkan membuat beranda terasa cepat dan profesional sejak detik pertama.</p>\n<h2 id=\"final-check-speed\">Pemeriksaan Terakhir Sebelum Menerbitkan</h2>\n<p>Jalankan lagi alat kecepatan untuk terakhir kalinya setelah semua gambar dioptimalkan. Pastikan total bobot gambar turun dan waktu muat membaik.</p>\n<p>Muat halaman di ponsel sungguhan lewat koneksi ponsel. Angka dalam uji lab memang berguna, tetapi rasa di ponsel adalah kebenarannya.</p>\n<p>Periksa setiap gambar secara visual sekali lagi. Halaman cepat dengan gambar utama yang buram bukanlah keberhasilan, dan pratinjau yang teliti menangkapnya.</p>\n<p>Uji halaman Anda dengan PageSpeed Insights, alat gratis dari Google. Ia memberi skor dan mencantumkan gambar mana yang paling membebani halaman Anda.</p>\n<p>WordPress punya plugin yang mengoptimasi gambar secara otomatis, tetapi hasilnya tidak selalu sebaik optimasi manual. Optimasi dulu dengan alat ini, lalu biarkan plugin menangani gambar yang baru diunggah.</p>\n<p>Perhatikan gambar di halaman beranda. Pengunjung pertama kali menilai situs dari beranda, dan gambar utama yang berat membuat kesan pertama itu lambat.</p>\n<p>Catat skor kecepatan sebelum dan sesudah optimasi. Angka yang membaik membuat manfaatnya nyata bagi klien atau tim Anda.</p>\n<h2 id=\"keep-learning\">Terus Belajar dari Setiap Halaman</h2>\n<p>Setiap halaman yang Anda optimasi mengajarkan sesuatu. Catat preset mana yang berhasil, gambar mana yang paling sulit, dan apa yang dilakukan angka kecepatan, karena pelajaran itu menumpuk dengan setiap halaman yang Anda perbaiki dan setiap situs yang Anda tingkatkan.</p>\n<p>Catatan itu menjadi buku pedoman Anda. Halaman berikutnya butuh waktu lebih sedikit karena halaman terakhir sudah menjawab pertanyaan-pertanyaannya.</p>\n<p>Untuk panduan lengkap alat optimasi, baca <a href=\"/id/blog/optimasi-gambar-website-panduan-lengkap/\">Optimasi Gambar Web: Panduan Lengkap</a>. Untuk penjelasan mendalam tentang Core Web Vitals, lihat <a href=\"/id/blog/optimasi-gambar-core-web-vitals-lcp-dan-ukuran-file/\">Optimasi Gambar untuk Core Web Vitals: LCP dan Ukuran File</a>. Untuk target ukuran sederhana, <a href=\"/id/kompres-gambar-menjadi-200-kb/\">alat kompres 200KB</a> mencakup kebanyakan gambar web.</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"Seberapa cepat situs saya setelah mengoptimasi gambar?","answer":"Tergantung seberapa berat gambarnya dulu. Halaman dengan 5MB gambar yang turun menjadi 500KB bisa termuat beberapa detik lebih cepat, terutama di ponsel. Jalankan uji kecepatan sebelum dan sesudah untuk melihat peningkatan persis bagi halaman Anda."},{"question":"Haruskah saya mengoptimasi gambar sebelum atau sesudah mengunggahnya ke situs saya?","answer":"Sebelumnya. Mengoptimasi dulu memberi Anda kendali atas dimensi, format, dan kualitas, ditambah tag HTML yang sudah jadi. Mengunggah dulu dan mengandalkan platform untuk mengompresnya biasanya menghasilkan hasil yang lebih buruk."},{"question":"Bisakah saya mengoptimasi tiga puluh gambar blog dalam satu batch?","answer":"Bisa. Tambahkan ketiga puluh gambar, pilih preset, dan unduh bersamaan. Lihat pratinjau beberapa hasil sebelum mengunduh seluruh batch, dan pertahankan preset yang konsisten supaya gambar tampak seragam di situs."},{"question":"Kenapa gambar utama saya tetap lambat setelah dioptimasi?","answer":"Periksa bahwa pemuatan malas mati untuk gambar utama, karena menundanya merusak kecepatan muat. Pastikan juga dimensi gambar utama cocok dengan ukuran tampilan; gambar utama yang terlalu besar membuang bandwidth. Memuat dulu gambar utama bisa membantu lebih lanjut."},{"question":"Apakah saya perlu memperbarui HTML ketika mengganti gambar?","answer":"Ya, jika dimensi atau nama filenya berubah. Tag HTML membawa lebar, tinggi, dan sumber, jadi tag yang kedaluwarsa bisa meregangkan gambar atau merusak tata letak. Salin tag baru dari alat kapan pun Anda mengganti gambar."},{"question":"Ukuran gambar berapa yang harus saya pakai untuk gambar fitur blog?","answer":"Samakan dengan ukuran tampilan tema Anda, biasanya selebar 1200 piksel atau kurang. Preset gambar utama atau kartu menangani ini secara otomatis. Menyajikan gambar dua kali lebih lebar daripada tampilannya membuang bandwidth tanpa manfaat yang terlihat."}];
